// ─── CONTACT PAGE ─────────────────────────────────────────────────────────────
function ContactPage() {
  const [form, setForm] = useState({ name: "", email: "", budget: "", message: "" });
  const [sent, setSent] = useState(false);

  const handle = (k, v) => setForm(f => ({ ...f, [k]: v }));
  const submit = () => { if (form.name && form.email && form.message) setSent(true); };

  return (
    <PageWrapper>
      <section style={{ padding: "4rem 0 5rem" }}>
        <p style={{ fontSize: 13, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "rgba(26,26,26,0.35)", marginBottom: 8 }}>Get In Touch</p>
        <h1 style={{ fontSize: "clamp(2.5rem, 5vw, 4rem)", fontWeight: 800, letterSpacing: "-0.04em", lineHeight: 1.05, marginBottom: "3rem" }}>
          Let's build something<br /><span style={{ fontFamily: "'Instrument Serif', serif", fontStyle: "italic", fontWeight: 400 }}>great together.</span>
        </h1>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1.2fr", gap: "5rem" }}>
          {/* Left info */}
          <div>
            <p style={{ fontSize: 17, lineHeight: 1.8, color: "rgba(26,26,26,0.55)", marginBottom: "2.5rem" }}>
              I'm currently available for freelance projects, long-term collaborations, and advisory roles. Reach out and let's talk about your next big idea.
            </p>
            {[
              { label: "Email", value: "okafor@design.co" },
              { label: "Location", value: "Lagos, Nigeria · Remote OK" },
              { label: "Response Time", value: "Within 24 hours" },
              { label: "Availability", value: "Open to new projects" },
            ].map(({ label, value }) => (
              <div key={label} style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", padding: "1rem 0", borderBottom: "1px solid rgba(26,26,26,0.07)" }}>
                <span style={{ fontSize: 14, fontWeight: 600, color: "rgba(26,26,26,0.38)", letterSpacing: "0.04em" }}>{label}</span>
                <span style={{ fontSize: 16, fontWeight: 600, color: "#1A1A1A" }}>{value}</span>
              </div>
            ))}

            <div style={{ marginTop: "2.5rem" }}>
              <p style={{ fontSize: 14, fontWeight: 700, letterSpacing: "0.06em", textTransform: "uppercase", color: "rgba(26,26,26,0.35)", marginBottom: "1rem" }}>Follow Me</p>
              <div style={{ display: "flex", gap: 10 }}>
                {["Dribbble","Behance","LinkedIn","Twitter"].map(s => (
                  <span key={s} style={{ padding: "7px 14px", borderRadius: 10, background: "#fff", border: "1px solid rgba(26,26,26,0.1)", fontSize: 14, fontWeight: 600, color: "rgba(26,26,26,0.55)", cursor: "pointer" }}>{s}</span>
                ))}
              </div>
            </div>
          </div>

          {/* Form */}
          <div style={{ background: "#fff", borderRadius: 24, padding: "2.5rem", border: "1px solid rgba(26,26,26,0.07)" }}>
            {sent ? (
              <div style={{ textAlign: "center", padding: "3rem 0" }}>
                <div style={{ fontSize: 48, marginBottom: "1rem" }}>✓</div>
                <h3 style={{ fontSize: 22, fontWeight: 800, letterSpacing: "-0.03em", marginBottom: "0.8rem" }}>Message Sent!</h3>
                <p style={{ fontSize: 16, color: "rgba(26,26,26,0.52)", lineHeight: 1.7 }}>Thanks for reaching out, {form.name}. I'll get back to you within 24 hours.</p>
                <button onClick={() => { setSent(false); setForm({ name: "", email: "", budget: "", message: "" }); }} style={{ marginTop: "1.5rem", padding: "10px 22px", borderRadius: 100, background: "#1A1A1A", color: "#F7F4EE", border: "none", fontSize: 15, fontWeight: 600, cursor: "pointer", fontFamily: "'Outfit', sans-serif" }}>Send Another</button>
              </div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: "1.2rem" }}>
                <h3 style={{ fontSize: 18, fontWeight: 800, letterSpacing: "-0.02em", marginBottom: "0.5rem" }}>Send a Message</h3>
                {[
                  { key: "name", label: "Your Name", placeholder: "John Doe" },
                  { key: "email", label: "Email Address", placeholder: "john@company.com" },
                  { key: "budget", label: "Project Budget (optional)", placeholder: "$5k – $10k" },
                ].map(({ key, label, placeholder }) => (
                  <div key={key}>
                    <label style={{ fontSize: 14, fontWeight: 700, color: "rgba(26,26,26,0.45)", letterSpacing: "0.04em", display: "block", marginBottom: 6 }}>{label}</label>
                    <input value={form[key]} onChange={e => handle(key, e.target.value)} placeholder={placeholder} style={{ width: "100%", padding: "11px 14px", borderRadius: 12, border: "1.5px solid rgba(26,26,26,0.12)", fontSize: 16, fontFamily: "'Outfit', sans-serif", color: "#1A1A1A", background: "#FAFAFA", outline: "none" }} />
                  </div>
                ))}
                <div>
                  <label style={{ fontSize: 14, fontWeight: 700, color: "rgba(26,26,26,0.45)", letterSpacing: "0.04em", display: "block", marginBottom: 6 }}>Message</label>
                  <textarea value={form.message} onChange={e => handle("message", e.target.value)} placeholder="Tell me about your project..." rows={5} style={{ width: "100%", padding: "11px 14px", borderRadius: 12, border: "1.5px solid rgba(26,26,26,0.12)", fontSize: 16, fontFamily: "'Outfit', sans-serif", color: "#1A1A1A", background: "#FAFAFA", outline: "none", resize: "vertical" }} />
                </div>
                <button onClick={submit} style={{ padding: "13px", borderRadius: 12, background: "#1A1A1A", color: "#F7F4EE", border: "none", fontSize: 16, fontWeight: 700, cursor: "pointer", fontFamily: "'Outfit', sans-serif", marginTop: "0.4rem" }}>Send Message →</button>
              </div>
            )}
          </div>
        </div>
      </section>
    </PageWrapper>
  );
}

