function ServiceCard({ service }) {
  const [hovered, setHovered] = useState(false);
  return (
    <div onMouseEnter={() => setHovered(true)} onMouseLeave={() => setHovered(false)} style={{ background: hovered ? "#1A1A1A" : "#fff", borderRadius: 20, padding: "1.8rem", border: "1px solid rgba(26,26,26,0.07)", cursor: "pointer", transition: "all 0.28s ease", transform: hovered ? "translateY(-4px)" : "translateY(0)", boxShadow: hovered ? "0 20px 48px rgba(26,26,26,0.14)" : "none" }}>
      <div style={{ fontSize: 13, fontWeight: 700, color: hovered ? "rgba(247,244,238,0.3)" : "rgba(26,26,26,0.2)", letterSpacing: "0.06em", marginBottom: "1.2rem", transition: "color 0.28s" }}>{service.num}</div>
      <h3 style={{ fontSize: 15, fontWeight: 700, marginBottom: 8, color: hovered ? "#F7F4EE" : "#1A1A1A", letterSpacing: "-0.01em", transition: "color 0.28s" }}>{service.title}</h3>
      <p style={{ fontSize: 13, lineHeight: 1.65, color: hovered ? "rgba(247,244,238,0.45)" : "rgba(26,26,26,0.48)", transition: "color 0.28s" }}>{service.desc}</p>
      <div style={{ marginTop: "1.4rem", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <span style={{ fontSize: 14, fontWeight: 600, color: hovered ? "rgba(247,244,238,0.3)" : "rgba(26,26,26,0.2)", transition: "color 0.28s" }}>Learn more</span>
        <span style={{ fontSize: 16, color: hovered ? "rgba(247,244,238,0.4)" : "rgba(26,26,26,0.18)", transition: "color 0.28s" }}>→</span>
      </div>
    </div>
  );
}

function ProjectCard({ project, hovered, setHovered }) {
  return (
    <div onMouseEnter={() => setHovered(project.id)} onMouseLeave={() => setHovered(null)} style={{ background: "#fff", borderRadius: 20, overflow: "hidden", border: "1px solid rgba(26,26,26,0.07)", cursor: "pointer", transition: "transform 0.3s ease, box-shadow 0.3s ease", transform: hovered ? "translateY(-6px)" : "translateY(0)", boxShadow: hovered ? "0 24px 56px rgba(26,26,26,0.13)" : "0 2px 8px rgba(26,26,26,0.04)" }}>
      <div style={{ height: 210, overflow: "hidden", position: "relative" }}>
        <Thumb type={project.thumb} />
        <div style={{ position: "absolute", inset: 0, background: "rgba(26,26,26,0.55)", display: "flex", alignItems: "center", justifyContent: "center", opacity: hovered ? 1 : 0, transition: "opacity 0.28s" }}>
          <div style={{ padding: "10px 22px", borderRadius: 100, background: "#F7F4EE", fontSize: 14, fontWeight: 700, color: "#1A1A1A", letterSpacing: "0.04em", fontFamily: "'Outfit', sans-serif" }}>View Case Study →</div>
        </div>
        <div style={{ position: "absolute", top: 12, right: 12, background: "rgba(247,244,238,0.92)", backdropFilter: "blur(6px)", borderRadius: 100, padding: "3px 11px", fontSize: 13, fontWeight: 700, color: "#1A1A1A" }}>{project.year}</div>
      </div>
      <div style={{ padding: "1.4rem 1.5rem" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
          <h3 style={{ fontSize: 15, fontWeight: 800, letterSpacing: "-0.02em" }}>{project.title}</h3>
          <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: "0.04em", color: project.accentDark, background: project.accentBg, borderRadius: 100, padding: "3px 10px", whiteSpace: "nowrap", marginLeft: 10, border: `1px solid ${project.accentDark}22` }}>{project.category}</span>
        </div>
        <p style={{ fontSize: 14.5, color: "rgba(26,26,26,0.48)", lineHeight: 1.65, marginBottom: "1rem" }}>{project.desc}</p>
        <div style={{ display: "flex", gap: 5 }}>
          {project.tags.map(t => <span key={t} style={{ fontSize: 13, fontWeight: 600, color: "rgba(26,26,26,0.38)", background: "rgba(26,26,26,0.05)", borderRadius: 6, padding: "3px 9px", border: "1px solid rgba(26,26,26,0.06)" }}>{t}</span>)}
        </div>
      </div>
    </div>
  );
}

